android.extraProguardRules:
# O R8 do release (ligado no SDK 58) apagava o banco do WorkManager, que vem pelo react-native-android-widget: o Room 2.5 acha a classe gerada por reflexão (#426).
-keep class * extends androidx.room.RoomDatabase { <init>(); }
-keep class androidx.work.impl.WorkDatabase_Impl { *; }

# O MediaPipe (tasks-vision 0.10.35) não traz regra de keep no AAR. As mensagens dele são protobuf-lite, que lê os campos por reflexão pelo nome (`platform_`), e o nativo chama classes Java por JNI: com o R8, a análise falhava em 'Field platform_ for kz3 not found'.
-keep class com.google.mediapipe.** { *; }
# O Flogger, que vem com o MediaPipe, acha quem o chamou procurando o próprio nome na pilha: renomeado, o Graph quebrava ao iniciar com 'no caller found on the stack'.
-keep class com.google.common.flogger.** { *; }
-dontwarn com.google.common.flogger.**
-keepclassmembers class * extends com.google.protobuf.GeneratedMessageLite { <fields>; }
-dontwarn com.google.mediapipe.**
